(13, 'Lắc Tay Mã Não Đỏ Tinh Xảo Phong Thủy', 'lac-tay-ma-nao-do-tinh-xao-phong-thuy-13', 'PC-LT-013', 'Lắc Tay làm từ mã não đỏ thiên nhiên, hỗ trợ mệnh Hỏa. Thiết kế tinh xảo, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Việt Nam, chọn lọc kỹ càng đảm bảo chất lượng.', 'Lắc Tay mã não đỏ, hợp mệnh Hỏa, phong cách tinh xảo.', 43, 37, 4912000.0, NULL, TRUE, 50, '{"material": "mã não đỏ", "element": "Hỏa", "origin": "Việt Nam", "style": "Tinh Xảo", "is_hot": false, "sold_count": 41}', 'active', 'pending'),
(14, 'Tỳ Hưu Thạch Anh Hồng Độc Đáo Phong Thủy', 'ty-huu-thach-anh-hong-doc-dao-phong-thuy-14', 'PC-TH-014', 'Tỳ Hưu làm từ thạch anh hồng thiên nhiên, hỗ trợ mệnh Kim, Thổ. Thiết kế độc đáo, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Brazil, chọn lọc kỹ càng đảm bảo chất lượng.', 'Tỳ Hưu thạch anh hồng, hợp mệnh Kim, Thổ, phong cách độc đáo.', 11, 9, 11246000.0, 10115000.0, TRUE, 54, '{"material": "thạch anh hồng", "element": "Kim, Thổ", "origin": "Brazil", "style": "Độc Đáo", "is_hot": false, "sold_count": 25}', 'active', 'pending'),
(15, 'Trâm Cài Ngọc Trai Akoya Sang Trọng Phong Thủy', 'tram-cai-ngoc-trai-akoya-sang-trong-phong-thuy-15', 'PC-TC-015', 'Trâm Cài làm từ ngọc trai Akoya thiên nhiên, hỗ trợ mệnh Thủy. Thiết kế sang trọng, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Nhật Bản, chọn lọc kỹ càng đảm bảo chất lượng.', 'Trâm Cài ngọc trai Akoya, hợp mệnh Thủy, phong cách sang trọng.', 13, 33, 1618000.0, 1249000.0, TRUE, 80, '{"material": "ngọc trai Akoya", "element": "Thủy", "origin": "Nhật Bản", "style": "Sang Trọng", "is_hot": false, "sold_count": 43}', 'active', 'pending'),
(16, 'Charm Phong Thủy Mã Não Trắng Thanh Lịch', 'charm-phong-thuy-ma-nao-trang-thanh-lich-16', 'PC-CM-016', 'Charm Phong Thủy làm từ mã não trắng thiên nhiên, hỗ trợ mệnh Kim. Thiết kế thanh lịch, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Việt Nam, chọn lọc kỹ càng đảm bảo chất lượng.', 'Charm Phong Thủy mã não trắng, hợp mệnh Kim, phong cách thanh lịch.', 14, 25, 9051000.0, 7243000.0, TRUE, 70, '{"material": "mã não trắng", "element": "Kim", "origin": "Việt Nam", "style": "Thanh Lịch", "is_hot": false, "sold_count": 0}', 'active', 'pending'),
(17, 'Nhẫn Đá Aventurine Xanh Lá Quý Phái Phong Thủy', 'nhan-da-aventurine-xanh-la-quy-phai-phong-thuy-17', 'PC-NH-017', 'Nhẫn làm từ đá aventurine xanh lá thiên nhiên, hỗ trợ mệnh Mộc. Thiết kế quý phái, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Ấn Độ, chọn lọc kỹ càng đảm bảo chất lượng.', 'Nhẫn đá aventurine xanh lá, hợp mệnh Mộc, phong cách quý phái.', 36, 49, 11594000.0, 9376000.0, TRUE, 20, '{"material": "đá aventurine xanh lá", "element": "Mộc", "origin": "Ấn Độ", "style": "Quý Phái", "is_hot": false, "sold_count": 46}', 'active', 'pending'),
