(19, 'Dây Chuyền San Hô Đỏ Quý Phái Phong Thủy', 'day-chuyen-san-ho-do-quy-phai-phong-thuy-19', 'PC-DC-019', 'Dây Chuyền làm từ san hô đỏ thiên nhiên, hỗ trợ mệnh Hỏa. Thiết kế quý phái, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Địa Trung Hải, chọn lọc kỹ càng đảm bảo chất lượng.', 'Dây Chuyền san hô đỏ, hợp mệnh Hỏa, phong cách quý phái.', 39, 1, 5052000.0, 4728000.0, TRUE, 39, '{"material": "san hô đỏ", "element": "Hỏa", "origin": "Địa Trung Hải", "style": "Quý Phái", "is_hot": false, "sold_count": 15}', 'active', 'pending'),
