(21, 'Charm Phong Thủy Lapis Lazuli Quý Phái', 'charm-phong-thuy-lapis-lazuli-quy-phai-21', 'PC-CM-021', 'Charm Phong Thủy làm từ lapis lazuli thiên nhiên, hỗ trợ mệnh Thủy. Thiết kế quý phái, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Afghanistan, chọn lọc kỹ càng đảm bảo chất lượng.', 'Charm Phong Thủy lapis lazuli, hợp mệnh Thủy, phong cách quý phái.', 14, 49, 10775000.0, 9529000.0, TRUE, 47, '{"material": "lapis lazuli", "element": "Thủy", "origin": "Afghanistan", "style": "Quý Phái", "is_hot": false, "sold_count": 33}', 'active', 'pending'),
