(34, 'Nhẫn Đá Mắt Hổ Vàng Tối Giản Phong Thủy', 'nhan-da-mat-ho-vang-toi-gian-phong-thuy-34', 'PC-NH-034', 'Nhẫn làm từ đá mắt hổ vàng thiên nhiên, hỗ trợ mệnh Kim, Thổ. Thiết kế tối giản, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Nam Phi, chọn lọc kỹ càng đảm bảo chất lượng.', 'Nhẫn đá mắt hổ vàng, hợp mệnh Kim, Thổ, phong cách tối giản.', 37, 40, 14943000.0, 11844000.0, TRUE, 33, '{"material": "đá mắt hổ vàng", "element": "Kim, Thổ", "origin": "Nam Phi", "style": "Tối Giản", "is_hot": true, "sold_count": 258}', 'active', 'pending'),
